{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "축음기에서는 소리가 나팔의 진동으로 바뀌면 그 진동의 형태에 따라 바늘이 판에 홈을 만들어 소리를 저장한다."
        },
        {
          "number": 2,
          "text": "오디오 파일은 저장하거나 네트워크로 전송하기에 데이터 양이 많으므로 저장 공간을 아끼고 전송이 가능하도록 압축할 필요가 있다."
        },
        {
          "number": 3,
          "text": "1,000 Hz부터 10,000 Hz 사이에서는 아주 작은 소리도 들을 수 있지만, 100 Hz 이하에서는 훨씬 큰 소리여야 들을 수 있다."
        },
        {
          "number": 4,
          "text": "지각부호화를 적용하기 전 한 파일 내의 오디오 신호에서는 소리 크기가 클수록 해당 소리 크기에 할당되는 비트의 개수가 많다."
        },
        {
          "number": 5,
          "text": "지각부호화에서는 차폐 문턱값보다 작은 소리를 청각으로 감지할 수 없으므로 이러한 소리를 제거하여 오디오 신호를 압축한다."
        }
      ],
      "answer": 4
    },
    {
      "slot": 2,
      "stem": "윗글의 내용에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "축음기는 소리를 아날로그 형태로 기록하였지만, 그 이후에 등장한 매체부터는 곧바로 소리를 디지털 형태로 기록하였다."
        },
        {
          "number": 2,
          "text": "지각부호화에서는 소리 크기와 차폐 문턱값의 차이가 클수록 해당 소리 크기에 더 많은 비트를 할당하여 소리의 손실을 낮춘다."
        },
        {
          "number": 3,
          "text": "소리를 디지털 신호로 저장할 때 각 소리 크기에 할당하는 비트의 개수가 늘어나면 소리는 아날로그 원음에서 더 멀어진다."
        },
        {
          "number": 4,
          "text": "지각부호화에서 이용하는 청각 특성인 최소가청강도는 조용할 때 청각이 감지할 수 있는 소리 크기의 최댓값을 의미한다."
        },
        {
          "number": 5,
          "text": "지각부호화에서는 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 먼저 구한 다음 오디오 신호를 주파수에 따라 여러 임계대역으로 나눈다."
        }
      ],
      "answer": 2
    },
    {
      "slot": 3,
      "stem": "차폐에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "차폐는 작은 소리 때문에 큰 소리가 청각에 감지되지 않는 현상이다."
        },
        {
          "number": 2,
          "text": "차폐 문턱값은 각 임계대역에서 차폐음을 고려하지 않고 최소가청강도만으로 정하는 값이다."
        },
        {
          "number": 3,
          "text": "차폐음이 고음일 때는 저음일 때보다 임계대역의 폭이 더 좁다."
        },
        {
          "number": 4,
          "text": "임계대역은 차폐음의 주파수부터 차폐가 일어날 수 있는 가장 높은 주파수까지의 구간이다."
        },
        {
          "number": 5,
          "text": "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어나지만 어느 정도 차이가 나면 차폐가 일어나지 않는다."
        }
      ],
      "answer": 5
    }
  ]
}

